import { getMatch } from '@/api/safeDanger/control/statistics';
export default {
  props: {
    // chartData: {
    //   type: Array,
    // }
  },
  data: function data() {
    return {
      chartData: [{
        value: 0,
        name: ''
      }]
    };
  },
  // watch: {
  //   chartData() {
  //     this.initChart()
  //   }
  // },
  mounted: function mounted() {
    this.getDetail();
  },
  methods: {
    getDetail: function getDetail() {
      var _this = this;
      getMatch().then(function (res) {
        _this.chartData[0].value = res.data.toFixed(0);
        _this.initChart();
      });
    },
    initChart: function initChart() {
      var areaChart = this.$echarts.init(document.getElementById('areaChart'));
      areaChart.setOption({
        tooltip: {
          formatter: '{a}: {b}'
        },
        // zoom: 10,
        series: [{
          type: 'gauge',
          data: this.chartData,
          radius: '87%',
          detail: {
            fontSize: 25,
            formatter: '{value}%'
          },
          axisLine: {
            lineStyle: {
              width: 20,
              color: [[0.3, "#fd666d"], [0.7, "#37a2da"], [1, "#67e0e3"]]
            }
          },
          pointer: {
            length: 100,
            width: 5
          }
        }]
      });
    }
  }
};
